select case when rating >= 3.6 then 'LARGE' else 'SMALL' end as rating_tier, city, round(sum(rating) / nullif(count(case when country = 'UK' then 1 end), 0), 2) as rating_per_uk, count_if(city = 'Bangkok') as bangkok_events, avg(rating) filter (where city = 'Tokyo') as tokyo_avg_rating, sum(rating) filter (where city = 'Singapore') as singapore_total_rating from suppliers group by rollup (case when rating >= 3.6 then 'LARGE' else 'SMALL' end, city);
